[CmdletBinding()]param([string]$PackageRoot)
$ErrorActionPreference='Stop';$PSNativeCommandUseErrorActionPreference=$false;if([string]::IsNullOrWhiteSpace($PackageRoot)){$PackageRoot=Split-Path -Parent $PSScriptRoot};$root=(Resolve-Path $PackageRoot).Path;$payload=Join-Path $root payload;$pm=Get-Content -Raw (Join-Path $root manifest.json)|ConvertFrom-Json;$nvcuda=Join-Path $env:WINDIR 'System32\nvcuda.dll';if(-not(Test-Path $nvcuda)){throw'NVIDIA driver not found'};$required=@('neural_reference_probe.exe','n0_dual_path_trace.ptx','n0_original.ptx','input_rgba16f.raw','weights.raw','params.raw');$actual=[ordered]@{};$integrity=$true;foreach($n in $required){$actual[$n]=(Get-FileHash (Join-Path $payload $n)).Hash;$integrity=$integrity-and$actual[$n]-eq$pm.payload_sha256.$n};$stamp=Get-Date -Format yyyyMMdd_HHmmss;$work=Join-Path $root "_n0_cta1_mma176_dual_path_work_$stamp";$result=Join-Path $root "_n0_cta1_mma176_dual_path_trace_reference_result_$stamp";New-Item -ItemType Directory -Path $work,$result|Out-Null
$probeJson=Join-Path $work probe.json;$scratch=Join-Path $work scratch.raw;$output=Join-Path $work output.raw;& (Join-Path $payload neural_reference_probe.exe) --nvcuda $nvcuda --ptx (Join-Path $payload n0_dual_path_trace.ptx) --function $pm.function --json $probeJson --n0-input (Join-Path $payload input_rgba16f.raw) --n0-weights (Join-Path $payload weights.raw) --n0-params (Join-Path $payload params.raw) --n0-scratch-out $scratch --n0-output $output --n0-grid-x 80 --n0-grid-y 48 --n0-scratch-extra-bytes ([int]$pm.scratch_extra_bytes) *> (Join-Path $work stdout.log);$probeExit=$LASTEXITCODE;$probe=Get-Content -Raw $probeJson|ConvertFrom-Json
$baseJson=Join-Path $work baseline_probe.json;$baseScratch=Join-Path $work baseline_scratch.raw;$baseOutput=Join-Path $work baseline_output.raw;& (Join-Path $payload neural_reference_probe.exe) --nvcuda $nvcuda --ptx (Join-Path $payload n0_original.ptx) --function $pm.function --json $baseJson --n0-input (Join-Path $payload input_rgba16f.raw) --n0-weights (Join-Path $payload weights.raw) --n0-params (Join-Path $payload params.raw) --n0-scratch-out $baseScratch --n0-output $baseOutput --n0-grid-x 80 --n0-grid-y 48 *> (Join-Path $work baseline_stdout.log);$baseExit=$LASTEXITCODE;$baseProbe=Get-Content -Raw $baseJson|ConvertFrom-Json
$trace=Join-Path $result dual_path_trace.raw;$s=[IO.File]::OpenRead($scratch);try{[void]$s.Seek([int64]$pm.trace_offset,[IO.SeekOrigin]::Begin);$b=[byte[]]::new([int]$pm.trace_bytes);$read=0;while($read-lt$b.Length){$n=$s.Read($b,$read,$b.Length-$read);if($n-eq 0){break};$read+=$n};if($read-ne$b.Length){throw"short trace $read"};[IO.File]::WriteAllBytes($trace,$b)}finally{$s.Dispose()};$nonzero=@($b|Where-Object{$_-ne 0}).Count;$oh=(Get-FileHash $output).Hash;$bh=(Get-FileHash $baseOutput).Hash;$preserved=$oh-eq$bh;$pass=$integrity-and$probeExit-eq 0-and$probe.pass-and$baseExit-eq 0-and$baseProbe.pass-and$preserved-and$nonzero-gt 0;Copy-Item $probeJson,$baseJson,(Join-Path $work stdout.log),(Join-Path $work baseline_stdout.log) $result
